INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','main','heroForm','{"heading": "Become a Foster Parent", "intro": "<p>Becoming a foster parent is a rewarding journey that gives you the opportunity to provide a <strong>safe, stable, and loving home</strong> for children in need. If you’ve ever felt the desire to <strong>make a difference</strong> in a child’s life, fostering may be the perfect way to do so.</p>", "bg": "image-set(url(''/assets/uploads/2024/10/shutterstock_1575539629-2-1917.avif'') type(''image/avif''), url(''/assets/uploads/2024/10/shutterstock_1575539629-2-1917.webp'') type(''image/webp''), url(''/assets/uploads/2024/10/shutterstock_1575539629-2.png''))"}',0,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','main','steps','{"heading": "How it Works", "steps": [{"reverse": true, "heading": "Interview / Initial Home Survey", "body": "<p>We begin with an interview and home visit to get to know you and assess the environment where you’ll be fostering. This informal survey helps us understand your motivation for fostering and ensures your home meets the basic safety requirements.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-2-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-2-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-2.jpg", "w": 834, "h": 468}}, {"reverse": true, "heading": "Complete and Submit Application Documents", "body": "<p>Next, you’ll complete the required application forms, which include background checks, references, and other important documentation. This step ensures that all necessary legal and safety requirements are met.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-3-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-3-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-3.jpg", "w": 834, "h": 468}}, {"reverse": true, "heading": "Home Study (Structured Analysis Family Evaluation)", "body": "<p>A thorough evaluation of your household is conducted through the Home Study process. This involves interviews, assessments, and home inspections to ensure your family is fully prepared to foster. The study helps us match you with the right child based on your strengths and family dynamics.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-1-e1730335908622-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-1-e1730335908622-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-1-e1730335908622.jpg", "w": 828, "h": 464}}, {"reverse": true, "heading": "Foster Parent Training", "body": "<p>Once your application and home study are complete, you’ll participate in our comprehensive foster parent training. This training covers topics such as trauma-informed care, child development, and behaviour management to equip you with the skills and knowledge needed to provide exceptional care.</p>", "img": {"avif": "/assets/uploads/2024/10/Frame-34130-4-640.avif 640w", "webp": "/assets/uploads/2024/10/Frame-34130-4-640.webp 640w", "jpg": "/assets/uploads/2024/10/Frame-34130-4.jpg", "w": 834, "h": 468}}]}',1,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','main','largeList','{"heading": "Possible Areas of Trauma", "items": [{"heading": "Oppositional Defiance Disorder:", "text": "Persistent disobedience, defiance, or hostility towards authority figures."}, {"heading": "Conduct Disorder:", "text": "A pattern of aggressive, disruptive, or anti-social behaviour."}, {"heading": "Obsessive Compulsive Disorder:", "text": "Repetitive behaviours or thoughts that can impact daily life."}, {"heading": "Fetal Alcohol Spectrum Disorder:", "text": "Developmental challenges due to prenatal alcohol exposure."}, {"heading": "Post-Traumatic Stress Disorder:", "text": "Emotional distress and trauma stemming from past experiences"}, {"heading": "Drug & Alcohol Abuse:", "text": "Struggles with substance use and addiction."}, {"heading": "Encounters with Law Enforcement:", "text": "Previous legal issues or encounters with the justice system."}, {"heading": "Absence Without Leave (AWOL):", "text": "Running away or being absent without permission."}, {"heading": "Stealing, Lying & Hoarding:", "text": "Behaviors that may stem from past trauma or survival instincts."}], "label": "Learn About Contact Us", "href": "/contact-us/"}',2,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','main','safety','{"content": "<h2>Support &amp; Safety</h2><p>The well-being of both the child and the foster family is a top priority at Safe Harbours. Within seven days of a child’s placement, a preliminary assessment will be conducted to identify any additional support needs.</p><h3 class=\"m-h4\"><strong>Our Goal</strong></h3><p>Our goal is to quickly integrate children into a routine whether by enrolling them in school, connecting them with relevant special needs staff, and/or initiating support from community mental health agencies. Based on the assessment, additional support may include:</p>", "cards": [{"text": "<b>Child and Youth Workers:</b><br>Professionals who provide guidance and support for the youth."}, {"text": "<b>Funding for Immediate Psychological Services:</b> Access to mental health resources as needed."}, {"text": "<b>Access to Community Support Programs:</b> Including drug counselors, therapists, and more."}, {"text": "<b>Educational Tutors: </b><br>To support the youth’s academic growth."}], "important": "<h4><strong>For Immediate Threats</strong></h4><p>If a child’s behaviour threatens the safety of the home or community, we will tap into our resource network to determine next steps.</p><p>In cases of an immediate threat, foster parents are advised to call the police, as maintaining a secure and safe home is essential, even if difficult decisions must be made.</p>"}',3,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','main','cta','{"heading": "Ready To Get Started?", "body": "<p><strong>Are you ready to make a difference?</strong> Safe Harbours is here to guide you every step of the way. Contact us today to learn more about fostering and how you can get involved. <strong>Your journey to becoming a foster parent begins here…</strong></p>", "label": "Get Started", "href": "/become-a-foster-parent/"}',4,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('become-a-foster-parent','main','logos','{"heading": "Referral Partners", "logos": [{"img": {"avif": "/assets/uploads/2024/11/Group-34247-640.avif 640w", "webp": "/assets/uploads/2024/11/Group-34247-640.webp 640w", "jpg": "/assets/uploads/2024/11/Group-34247.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34246-640.avif 640w", "webp": "/assets/uploads/2024/11/Group-34246-640.webp 640w", "jpg": "/assets/uploads/2024/11/Group-34246.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34245-399.avif 399w", "webp": "/assets/uploads/2024/11/Group-34245-399.webp 399w", "jpg": "/assets/uploads/2024/11/Group-34245.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34244-537.avif 537w", "webp": "/assets/uploads/2024/11/Group-34244-537.webp 537w", "jpg": "/assets/uploads/2024/11/Group-34244.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34243-576.avif 576w", "webp": "/assets/uploads/2024/11/Group-34243-576.webp 576w", "jpg": "/assets/uploads/2024/11/Group-34243.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34237-522.avif 522w", "webp": "/assets/uploads/2024/11/Group-34237-522.webp 522w", "jpg": "/assets/uploads/2024/11/Group-34237.png"}}, {"img": {"avif": "/assets/uploads/2024/11/Group-34236-640.avif 640w, /assets/uploads/2024/11/Group-34236-1024.avif 1024w", "webp": "/assets/uploads/2024/11/Group-34236-640.webp 640w, /assets/uploads/2024/11/Group-34236-1024.webp 1024w", "jpg": "/assets/uploads/2024/11/Group-34236.png"}}]}',5,'published','');
